{
  "expo": {
    "name": "MyApp",
    "slug": "my-app",
    "version": "1.0.0",
    "orientation": "portrait",
    "scheme": "myapp",
    "icon": "./assets/icon.png",
    "userInterfaceStyle": "dark",
    "splash": {
      "image": "./assets/splash-icon.png",
      "resizeMode": "contain",
      "backgroundColor": "#0d0d0d"
    },
    "ios": {
      "supportsTablet": false,
      "bundleIdentifier": "com.yourcompany.myapp",
      "associatedDomains": [
        "applinks:REPLACE_WITH_YOUR_DOMAIN"
      ]
    },
    "android": {
      "package": "com.yourcompany.myapp",
      "adaptiveIcon": {
        "foregroundImage": "./assets/icon.png",
        "backgroundColor": "#0d0d0d"
      },
      "permissions": [
        "android.permission.CAMERA",
        "android.permission.READ_EXTERNAL_STORAGE",
        "android.permission.WRITE_EXTERNAL_STORAGE"
      ],
      "androidStatusBar": {
        "barStyle": "light-content",
        "backgroundColor": "#0d0d0d",
        "translucent": true
      },
      "predictiveBackGestureEnabled": false,
      "intentFilters": [
        {
          "action": "VIEW",
          "autoVerify": true,
          "data": [
            { "scheme": "myapp" }
          ],
          "category": ["BROWSABLE", "DEFAULT"]
        }
      ]
    },
    "web": {
      "favicon": "./assets/icon.png"
    },
    "plugins": [
      "expo-router",
      "expo-image",
      [
        "expo-splash-screen",
        {
          "backgroundColor": "#0d0d0d",
          "image": "./assets/splash-icon.png",
          "imageWidth": 200
        }
      ],
      "expo-secure-store",
      "expo-localization",
      "expo-font",
      [
        "@sentry/react-native/expo",
        {
          "url": "https://sentry.io/",
          "project": "react-native",
          "organization": "your-org"
        }
      ],
      "@sentry/react-native"
    ],
    "extra": {
      "router": {},
      "eas": {
        "projectId": "REPLACE_WITH_YOUR_EAS_PROJECT_ID"
      }
    },
    "owner": "REPLACE_WITH_YOUR_EXPO_OWNER"
  }
}

/**
 * 🏷️ APP IDENTITY — Change these values to rebrand the app.
 *
 * These are referenced across landing, auth, onboarding, and profile screens.
 * Update them once here and they propagate everywhere.
 *
 * Steps to rebrand:
 *   1. Change APP_NAME, APP_TAGLINE, and APP_DESCRIPTION below
 *   2. Update app.json → expo.name and expo.slug
 *   3. Change ACCENT in lib/theme.ts for color rebrand
 */

/** Display name shown in headers, onboarding, and the landing page. */
export const APP_NAME = 'MyApp'

/** URL scheme matching expo.scheme in app.json — used for OAuth deep link callbacks. */
export const APP_SCHEME = 'myapp'

/** Support email shown on the Support screen. */
export const APP_SUPPORT_EMAIL = 'support@example.com'

/** Documentation URL shown on the Support screen. */
export const APP_DOCS_URL = 'https://example.com/docs'

/** One-liner shown on the landing page below the app name. */
export const APP_TAGLINE = 'Your next great idea starts here.'

/** Short description used in marketing / onboarding contexts. */
export const APP_DESCRIPTION =
  'A production-ready mobile app template with auth, subscriptions, analytics, and polished UI — ready from day one.'

import React, { useEffect, useState } from 'react'
import { View, StyleSheet, Platform, DeviceEventEmitter } from 'react-native'
import { Stack, useNavigationContainerRef, usePathname } from 'expo-router'
import { QueryClientProvider } from '@tanstack/react-query'
import { queryClient } from '@/lib/queryClient'
import * as Sentry from '@sentry/react-native'

const routingInstrumentation = Sentry.reactNavigationIntegration()

Sentry.init({
  dsn: process.env.EXPO_PUBLIC_SENTRY_DSN ?? '',
  environment: __DEV__ ? 'development' : 'production',
  enabled: !__DEV__ && !!process.env.EXPO_PUBLIC_SENTRY_DSN,
  integrations: [routingInstrumentation],
  tracesSampleRate: 0,
})

import { GestureHandlerRootView } from 'react-native-gesture-handler'
import { BottomSheetModalProvider } from '@gorhom/bottom-sheet'
import { SafeAreaProvider } from 'react-native-safe-area-context'
import { StatusBar } from 'expo-status-bar'
import { useFonts } from 'expo-font'
import {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  Inter_800ExtraBold,
} from '@expo-google-fonts/inter'
import { ThemeProvider, DarkTheme } from '@react-navigation/native'
import { PostHogProvider } from 'posthog-react-native'
import { I18nextProvider } from 'react-i18next'

import { supabase, isSupabaseEnabled } from '@/lib/supabase'
import { posthog, isPostHogEnabled, identify, resetIdentity, track } from '@/lib/analytics'
import { configureRevenueCat, loginRevenueCat, logoutRevenueCat } from '@/lib/purchases'
import { SubscriptionProvider } from '@/contexts/SubscriptionContext'
import { ToastProvider } from '@/contexts/ToastContext'
import i18n, { initI18n } from '@/lib/i18n'
import OfflineBanner from '@/components/OfflineBanner'
import OfflineOverlay from '@/components/OfflineOverlay'
import { Text } from '@/components/ui/Text'
import { BG } from '@/lib/theme'

// ─── Error boundary ───────────────────────────────────────────────────────────
// React requires a class component to catch render errors — hooks cannot do this.

function ErrorFallback() {
  return (
    <View style={eb.container}>
      <Text style={eb.title}>Something went wrong</Text>
      <Text style={eb.subtitle}>Please close and reopen the app.</Text>
    </View>
  )
}

class ErrorBoundary extends React.Component<
  { children: React.ReactNode },
  { hasError: boolean }
> {
  state = { hasError: false }

  static getDerivedStateFromError() {
    return { hasError: true }
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('[ErrorBoundary] Uncaught error:', error, info)
    Sentry.captureException(error, { extra: { componentStack: info.componentStack } })
  }

  render() {
    if (this.state.hasError) return <ErrorFallback />
    return this.props.children
  }
}

const eb = StyleSheet.create({
  container: {
    flex: 1, backgroundColor: BG,
    alignItems: 'center', justifyContent: 'center', padding: 32,
  },
  title: { color: '#fff', fontSize: 18, fontWeight: '700', marginBottom: 10, textAlign: 'center' },
  subtitle: { color: 'rgba(255,255,255,0.4)', fontSize: 14, textAlign: 'center', lineHeight: 22 },
})

// ─── Theme ────────────────────────────────────────────────────────────────────

const customDarkTheme = {
  ...DarkTheme,
  colors: { ...DarkTheme.colors, background: BG },
}

// ─── Conditional PostHog provider ─────────────────────────────────────────────
// PostHogProvider requires a valid client instance. When the API key is missing
// we skip the provider entirely so no errors are thrown.

function MaybePostHogProvider({ children }: { children: React.ReactNode }) {
  if (isPostHogEnabled && posthog) {
    return <PostHogProvider client={posthog}>{children}</PostHogProvider>
  }
  return <>{children}</>
}

// ─── Screen tracking ─────────────────────────────────────────────────────────
// Rendered inside the navigator so usePathname has routing context.

function ScreenTracker() {
  const pathname = usePathname()
  useEffect(() => {
    track('screen_viewed', { screen: pathname })
  }, [pathname])
  return null
}

// ─── Root layout ──────────────────────────────────────────────────────────────

function RootLayout() {
  const navigationRef = useNavigationContainerRef()
  const [fontsLoaded] = useFonts({
    Inter_400Regular,
    Inter_500Medium,
    Inter_600SemiBold,
    Inter_700Bold,
    Inter_800ExtraBold,
  })

  // null = still checking; true/false = auth state known
  const [isAuthed, setIsAuthed] = useState<boolean | null>(null)
  // null = loading; false = not completed; true = completed
  const [onboardingCompleted, setOnboardingCompleted] = useState<boolean | null>(null)
  const [i18nReady, setI18nReady] = useState(false)

  useEffect(() => {
    initI18n().then(() => setI18nReady(true))
  }, [])

  useEffect(() => {
    if (navigationRef.current) {
      routingInstrumentation.registerNavigationContainer(navigationRef)
    }
  }, [navigationRef])

  useEffect(() => {
    // Configure RevenueCat once at startup, before any user is known
    configureRevenueCat()

    if (!isSupabaseEnabled) {
      // No credentials — stay on landing page, no errors thrown
      setIsAuthed(false)
      return
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      setIsAuthed(!!session)
      if (session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
        loginRevenueCat(session.user.id)
        identify(
          session.user.id,
          session.user.email ? { email: session.user.email } : undefined
        )
      } else {
        setOnboardingCompleted(null)
      }
    }).catch(() => {
      console.warn('[Auth] Could not reach Supabase — defaulting to signed-out state.')
      setIsAuthed(false)
    })

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        setIsAuthed(true)
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
        loginRevenueCat(session.user.id)
        identify(
          session.user.id,
          session.user.email ? { email: session.user.email } : undefined
        )
      }
      if (event === 'SIGNED_OUT') {
        setIsAuthed(false)
        setOnboardingCompleted(null)
        logoutRevenueCat()
        resetIdentity()
      }
      if (event === 'USER_UPDATED' && session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
      }
      if (event === 'TOKEN_REFRESHED' && session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
      }
    })

    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (!__DEV__) return
    const sub = DeviceEventEmitter.addListener('__dev_skip_auth__', () => {
      setIsAuthed(true)
      setOnboardingCompleted(true)
    })
    return () => sub.remove()
  }, [])

  // Show blank dark screen while session + i18n checks complete.
  // This prevents a flash of wrong content on launch.
  if (!fontsLoaded || isAuthed === null || !i18nReady || (isAuthed === true && onboardingCompleted === null)) {
    return <View style={{ flex: 1, backgroundColor: BG }} />
  }

  return (
    <ErrorBoundary>
      <I18nextProvider i18n={i18n}>
        <MaybePostHogProvider>
          <QueryClientProvider client={queryClient}>
          <SubscriptionProvider>
            <ToastProvider>
            <SafeAreaProvider>
              <GestureHandlerRootView style={{ flex: 1, backgroundColor: BG }}>
                <BottomSheetModalProvider>
                  <StatusBar
                    style="light"
                    translucent={Platform.OS === 'android'}
                    backgroundColor={Platform.OS === 'android' ? BG : undefined}
                  />
                  <ThemeProvider value={customDarkTheme}>
                    <View style={{ flex: 1, backgroundColor: BG }}>
                      <Stack ref={navigationRef} screenOptions={{ headerShown: false, animation: 'fade', contentStyle: { backgroundColor: BG } }}>

                        {/* ── Unauthenticated screens ──────────────────────────────────
                        Accessible only when signed out. When isAuthed flips to true,
                        Stack.Protected removes these and Expo Router auto-redirects to
                        the first accessible authenticated screen. */}
                        <Stack.Protected guard={!isAuthed}>
                          <Stack.Screen name="index" />
                          <Stack.Screen name="(auth)" />
                        </Stack.Protected>

                        {/* ── Onboarding screens ───────────────────────────────────────
                        Shown when signed in but onboarding not yet completed. */}
                        <Stack.Protected guard={!!isAuthed && onboardingCompleted === false}>
                          <Stack.Screen name="(onboarding)" />
                        </Stack.Protected>

                        {/* ── Authenticated screens ────────────────────────────────────
                        Accessible only when signed in + onboarding done. */}
                        <Stack.Protected guard={!!isAuthed && onboardingCompleted === true}>
                          <Stack.Screen name="(tabs)" />
                          <Stack.Screen name="detail/[id]" />
                          <Stack.Screen name="settings" />
                          <Stack.Screen name="support" />
                        </Stack.Protected>

                        {/* ── Always-public screens — declared LAST so they don't become
                        the default redirect target when a protected group flips. ── */}
                        <Stack.Screen name="upgrade" />
                        <Stack.Screen name="privacy" />
                        <Stack.Screen name="terms" />
                      </Stack>
                      <ScreenTracker />
                      <OfflineBanner />
                      <OfflineOverlay />
                    </View>
                  </ThemeProvider>
                </BottomSheetModalProvider>
              </GestureHandlerRootView>
            </SafeAreaProvider>
            </ToastProvider>
          </SubscriptionProvider>
          </QueryClientProvider>
        </MaybePostHogProvider>
      </I18nextProvider>
    </ErrorBoundary>
  )
}

export default Sentry.wrap(RootLayout)

/** @type {import('tailwindcss').Config} */

// 🎨 BRAND: Change 'accent' to your brand color.
// All NativeWind classes using bg-accent, text-accent, border-accent update automatically.
// Also update Theme.accent in lib/theme.ts to match.

module.exports = {
  content: ['./app/**/*.{ts,tsx}', './components/**/*.{ts,tsx}'],
  presets: [require('nativewind/preset')],
  theme: {
    extend: {
      colors: {
        background: '#0d0d0d',
        accent: '#0ea5a4',      // 🎨 BRAND: your primary accent color
        surface: '#1a1a1a',
        surface2: '#242424',
        muted: '#6b7280',
      },
    },
  },
  plugins: [],
}

import React, { useEffect } from 'react'
import { View, Pressable, StyleSheet, Platform } from 'react-native'
import type { BottomTabBarProps } from '@react-navigation/bottom-tabs'
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  Easing,
} from 'react-native-reanimated'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { BlurView } from 'expo-blur'
import {
  TAB_ACTIVE,
  TAB_INACTIVE,
  TAB_HEIGHT,
  BG,
} from '@/lib/theme'
import { Text } from '@/components/ui/Text'

// ─── Tab icon definitions ─────────────────────────────────────────────────────
// Add new tabs here after creating the corresponding app/(tabs)/<name>.tsx file.

const ICON_SIZE = 26
const INDICATOR_W = 40
const EASE_OUT = Easing.out(Easing.cubic)
const EASE_IN = Easing.in(Easing.cubic)

export const TAB_BAR_HEIGHT = TAB_HEIGHT
export const TAB_BAR_CLEARANCE = TAB_HEIGHT + 4

// ─── Single tab item ──────────────────────────────────────────────────────────

function TabItem({
  label,
  isActive,
  onPress,
  icon,
}: {
  label: string
  isActive: boolean
  onPress: () => void
  icon?: React.ReactNode
}) {
  const indicatorW = useSharedValue(isActive ? INDICATOR_W : 0)
  const pressOpacity = useSharedValue(1)

  useEffect(() => {
    indicatorW.value = withTiming(isActive ? INDICATOR_W : 0, {
      duration: isActive ? 200 : 150,
      easing: isActive ? EASE_OUT : EASE_IN,
    })
  }, [isActive])

  const indicatorStyle = useAnimatedStyle(() => ({ width: indicatorW.value }))
  const pressStyle = useAnimatedStyle(() => ({ opacity: pressOpacity.value }))

  return (
    <Pressable
      style={s.tab}
      onPress={onPress}
      onPressIn={() => { pressOpacity.value = withTiming(0.45, { duration: 70 }) }}
      onPressOut={() => { pressOpacity.value = withTiming(1, { duration: 160, easing: EASE_OUT }) }}
      accessibilityRole="tab"
      accessibilityState={{ selected: isActive }}
    >
      {/* Active indicator line at top */}
      <Animated.View style={[s.indicator, indicatorStyle]} />

      <Animated.View style={[s.tabInner, pressStyle]}>
        {icon}
        <Text style={[s.label, isActive && s.labelActive]} numberOfLines={1}>
          {label}
        </Text>
      </Animated.View>
    </Pressable>
  )
}

// ─── TabBar ───────────────────────────────────────────────────────────────────

export default function TabBar({ state, navigation, descriptors }: BottomTabBarProps) {
  const insets = useSafeAreaInsets()

  function handlePress(name: string, key: string, i: number) {
    if (state.index === i) return
    const ev = navigation.emit({ type: 'tabPress', target: key, canPreventDefault: true })
    if (!ev.defaultPrevented) navigation.navigate(name as never)
  }

  const tabs = (
    <View style={s.bar}>
      {state.routes.map((route, i) => {
        const { options } = descriptors[route.key]
        const isActive = state.index === i
        const label = typeof options.tabBarLabel === 'string'
          ? options.tabBarLabel
          : (options.title ?? route.name)
        const icon = options.tabBarIcon?.({
          color: isActive ? TAB_ACTIVE : TAB_INACTIVE,
          size: ICON_SIZE,
          focused: isActive,
        })

        return (
          <TabItem
            key={route.key}
            label={label}
            isActive={isActive}
            icon={icon}
            onPress={() => handlePress(route.name, route.key, i)}
          />
        )
      })}
    </View>
  )

  if (Platform.OS === 'ios') {
    return (
      <View style={s.wrapper}>
        <BlurView intensity={30} tint="dark" style={StyleSheet.absoluteFill} />
        <View style={s.overlay} />
        {tabs}
        {insets.bottom > 0 && (
          <View style={{ height: insets.bottom, backgroundColor: 'transparent' }} />
        )}
      </View>
    )
  }

  return (
    <View style={[s.wrapper, s.wrapperAndroid]}>
      {tabs}
      {insets.bottom > 0 && (
        <View style={{ height: insets.bottom, backgroundColor: BG }} />
      )}
    </View>
  )
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const s = StyleSheet.create({
  wrapper: {
    position: 'absolute', left: 0, right: 0, bottom: 0,
    borderTopLeftRadius: 20, borderTopRightRadius: 20,
    overflow: 'hidden',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -4 },
    shadowOpacity: 0.3, shadowRadius: 12,
    elevation: 20,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: 'rgba(255,255,255,0.08)',
  },
  wrapperAndroid: { backgroundColor: BG },
  overlay: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: `${BG}B8`, // BG at ~72% opacity
  },
  bar: {
    flexDirection: 'row', height: TAB_HEIGHT, alignItems: 'stretch',
  },
  tab: {
    flex: 1, alignItems: 'center', justifyContent: 'flex-start',
  },
  indicator: {
    height: 3, borderRadius: 2,
    backgroundColor: TAB_ACTIVE,
    marginBottom: 6,
  },
  tabInner: {
    alignItems: 'center', justifyContent: 'center', gap: 5,
  },
  label: {
    fontSize: 10.5, color: TAB_INACTIVE, textAlign: 'center', fontWeight: '500',
  },
  labelActive: {
    color: TAB_ACTIVE, fontWeight: '600',
  },
})

/**
 * Tabs layout — add new tabs by:
 *   1. Create app/(tabs)/<name>.tsx
 *   2. Add a tabBarIcon and tabBarLabel in the <Tabs.Screen> below.
 *
 * The custom TabBar renders itself — its tab list is driven entirely by
 * the screens registered here.
 */
import { Tabs } from 'expo-router'
import { House, Compass, Bell, CircleUser } from 'lucide-react-native'
import TabBar, { TAB_BAR_HEIGHT } from '@/components/TabBar'
import { BG } from '@/lib/theme'

export default function TabsLayout() {
  return (
    <Tabs
      tabBar={(props) => <TabBar {...props} />}
      screenOptions={{
        headerShown: false,
        sceneStyle: { backgroundColor: BG },
        // Extra bottom padding so content clears the floating tab bar
        tabBarStyle: { height: TAB_BAR_HEIGHT },
      }}
    >
      <Tabs.Screen
        name="index"
        options={{
          tabBarLabel: 'Home',
          tabBarIcon: ({ color, size }) => (
            <House size={size} color={color} strokeWidth={1.6} />
          ),
        }}
      />

      <Tabs.Screen
        name="explore"
        options={{
          tabBarLabel: 'Explore',
          tabBarIcon: ({ color, size }) => (
            <Compass size={size} color={color} strokeWidth={1.6} />
          ),
        }}
      />

      <Tabs.Screen
        name="activity"
        options={{
          tabBarLabel: 'Activity',
          tabBarIcon: ({ color, size }) => (
            <Bell size={size} color={color} strokeWidth={1.6} />
          ),
        }}
      />

      <Tabs.Screen
        name="profile"
        options={{
          tabBarLabel: 'Profile',
          tabBarIcon: ({ color, size }) => (
            <CircleUser size={size} color={color} strokeWidth={1.6} />
          ),
        }}
      />
    </Tabs>
  )
}

import { useMemo, useState, useEffect } from 'react'
import { View, ScrollView, StyleSheet, Pressable } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { Ionicons } from '@expo/vector-icons'
import { Text } from '@/components/ui/Text'
import { Card } from '@/components/ui/Card'
import {
    ACCENT,
    BG,
    BORDER,
    TEXT_PRIMARY,
    TEXT_SECONDARY,
    TEXT_TERTIARY,
} from '@/lib/theme'
import { TAB_BAR_CLEARANCE } from '@/components/TabBar'
import { useNotifications } from '@/hooks/useNotifications'
import type { NotificationItem } from '@/lib/mockData'

type TabType = 'all' | 'unread'

export default function ActivityScreen() {
    const insets = useSafeAreaInsets()
    const [activeTab, setActiveTab] = useState<TabType>('all')
    const { data: remoteItems = [] } = useNotifications()
    const [items, setItems] = useState<NotificationItem[]>(remoteItems)

    // Sync local state when remote data arrives
    useEffect(() => {
        if (remoteItems.length > 0) setItems(remoteItems)
    }, [remoteItems])

    const visibleItems = useMemo(() => {
        if (activeTab === 'all') return items
        return items.filter((item) => !item.read)
    }, [activeTab, items])

    const unreadCount = useMemo(() => items.filter((item) => !item.read).length, [items])

    const markAllRead = () => {
        setItems((prev) => prev.map((item) => ({ ...item, read: true })))
    }

    const toggleRead = (id: string) => {
        setItems((prev) => prev.map((item) => item.id === id ? { ...item, read: !item.read } : item))
    }

    return (
        <ScrollView
            style={{ flex: 1, backgroundColor: BG }}
            contentContainerStyle={[s.container, { paddingTop: insets.top + 16, paddingBottom: TAB_BAR_CLEARANCE + 16 }]}
            showsVerticalScrollIndicator={false}
        >
            <View style={s.header}>
                <View>
                    <Text style={s.title}>Activity</Text>
                    <Text style={s.subtitle}>Product updates, team events, and billing alerts.</Text>
                </View>

                <Pressable onPress={markAllRead} style={({ pressed }) => [s.markAllBtn, pressed && { opacity: 0.75 }]}
                >
                    <Text style={s.markAllText}>Mark all read</Text>
                </Pressable>
            </View>

            <View style={s.segmentRow}>
                <Pressable
                    onPress={() => setActiveTab('all')}
                    style={[s.segmentItem, activeTab === 'all' && s.segmentItemActive]}
                >
                    <Text style={[s.segmentText, activeTab === 'all' && s.segmentTextActive]}>All ({items.length})</Text>
                </Pressable>
                <Pressable
                    onPress={() => setActiveTab('unread')}
                    style={[s.segmentItem, activeTab === 'unread' && s.segmentItemActive]}
                >
                    <Text style={[s.segmentText, activeTab === 'unread' && s.segmentTextActive]}>Unread ({unreadCount})</Text>
                </Pressable>
            </View>

            {visibleItems.length === 0 ? (
                <Card style={s.emptyCard}>
                    <Text style={s.emptyTitle}>You are all caught up</Text>
                    <Text style={s.emptySub}>New alerts and updates will appear here.</Text>
                </Card>
            ) : (
                <Card style={s.listCard}>
                    {visibleItems.map((item, index) => (
                        <Pressable
                            key={item.id}
                            onPress={() => toggleRead(item.id)}
                            style={[s.row, index < visibleItems.length - 1 && s.rowDivider]}
                        >
                            <View style={[s.iconWrap, item.read && s.iconWrapMuted]}>
                                <Ionicons name={categoryIcon(item.category)} size={14} color={item.read ? TEXT_SECONDARY : ACCENT} />
                            </View>

                            <View style={{ flex: 1 }}>
                                <Text style={[s.rowTitle, item.read && s.rowTitleMuted]}>{item.title}</Text>
                                <Text style={s.rowBody}>{item.body}</Text>
                                <Text style={s.rowTime}>{item.timeAgo}</Text>
                            </View>

                            {!item.read && <View style={s.unreadDot} />}
                        </Pressable>
                    ))}
                </Card>
            )}
        </ScrollView>
    )
}

function categoryIcon(category: 'billing' | 'system' | 'product' | 'team') {
    switch (category) {
        case 'billing':
            return 'wallet-outline'
        case 'system':
            return 'server-outline'
        case 'product':
            return 'sparkles-outline'
        case 'team':
            return 'people-outline'
        default:
            return 'ellipse-outline'
    }
}

