import { useState } from 'react'
import { View, ScrollView, StyleSheet, Pressable } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { Text } from '@/components/ui/Text'
import AdviceCard, { type AdviceData } from '@/components/AdviceCard'
import { TAB_BAR_CLEARANCE } from '@/components/TabBar'
import { colors, radii, spacing, typeScale } from '@/lib/design/tokens'

// ─── Mock advice data ─────────────────────────────────────────────────────────

const MOCK_ADVICES: AdviceData[] = [
  {
    headline: "You hold the leverage — the question is how much of it you're willing to use.",
    strategy:
      "Walk in with the competing offer as a fact, not a threat. Your goal is a counter that reflects your market value, not a bidding war. Give your manager a genuine chance to respond before you've emotionally committed to leaving — it protects the relationship if you stay, and your integrity if you go.",
    talkingPoints: [
      "Schedule a private, in-person meeting — not Slack, not email.",
      "Say: 'I've received an outside offer and wanted to be transparent before responding.'",
      "State the number plainly: 'It's 30% above my current base.'",
      "Ask directly: 'Is there room to have a compensation conversation here?'",
      "Give them 48 hours to come back with something concrete.",
    ],
    likelyOutcomes: {
      best: "The company matches or comes close, you stay with the team you value, and your pay is now market-rate.",
      likely:
        "They offer a partial match of 10–20%, which forces a genuine decision about what the gap is worth to you.",
      worst:
        "They decline to move, the relationship becomes strained, and you leave — but knowing you gave it a fair chance.",
    },
    followUps: [
      "Get the revised number in writing before declining the outside offer.",
      "If salary is fixed, ask about equity, title, or expanded scope instead.",
      "Set a personal deadline — do not let this drag beyond 5 business days.",
    ],
    riskFlags: [
      "Framing the offer as an ultimatum rather than a data point will damage trust even if it works.",
    ],
  },
  {
    headline: "This conversation will not fix the relationship — but it might clarify whether one is worth having.",
    strategy:
      "The goal isn't to win the argument; it's to be heard and to understand what you're actually dealing with. Approach it as a fact-finding conversation, not a confrontation. Stay specific: behavior and impact, not character and motive. If the other person escalates, that's data.",
    talkingPoints: [
      "Start with: 'I want to talk about something that's been affecting my ability to work well here.'",
      "Name the specific behavior, not the person's intent: 'When X happens, it creates Y problem.'",
      "Pause after each point — don't fill silence. Let them respond.",
      "If they deny or deflect, say: 'I hear you see it differently. I'm describing my experience.'",
      "End with a clear ask: 'What I'm hoping for is Z going forward.'",
    ],
    likelyOutcomes: {
      best:
        "They acknowledge the issue, you agree on a changed dynamic, and the working relationship improves measurably.",
      likely:
        "The conversation is uncomfortable, nothing resolves immediately, but you've created a documented record and set a clear expectation.",
      worst:
        "They become defensive or retaliatory — which tells you this environment isn't safe and you need a different plan.",
    },
    followUps: [
      "Send a brief follow-up email summarizing what was discussed and agreed.",
      "Give it two weeks before assessing whether anything changed.",
      "If nothing changes, bring it to HR or your manager's manager with your notes.",
    ],
    riskFlags: [
      "Having this conversation via text or email removes all tone — do it face-to-face or on a call.",
      "If you're in a legally sensitive situation (harassment, discrimination), speak to HR first.",
    ],
  },
  {
    headline: "The deal is closer than they're letting on — patience is now your sharpest negotiating tool.",
    strategy:
      "They've come back twice. That signals interest they won't admit to. Your position: hold the line on the key terms, show flexibility on the secondary ones, and let silence do work. The next person to move first loses ground. You don't need to be aggressive — you need to be unhurried.",
    talkingPoints: [
      "Restate your position calmly: 'We're at X on the core terms. That hasn't changed.'",
      "Offer a small concession on something low-cost to you: payment schedule, delivery window.",
      "Ask: 'What specifically is blocking agreement on your end?'",
      "If they push on price, ask: 'What would need to be true for this to work at your number?'",
      "Do not respond to counter-offers the same day — wait 24 hours minimum.",
    ],
    likelyOutcomes: {
      best: "They accept your terms or come within 5% — deal closes this week.",
      likely:
        "One more round of back-and-forth on a secondary term, then it closes on terms close to yours.",
      worst:
        "They walk. Which means your price was right and they weren't a good-faith counterparty.",
    },
    followUps: [
      "Draft the agreement outline now so you can move fast when they say yes.",
      "Identify your true walk-away number internally — don't drift from it under pressure.",
    ],
    riskFlags: [],
  },
]

// ─── Screen ───────────────────────────────────────────────────────────────────

export default function AdviseScreen() {
  const insets = useSafeAreaInsets()
  const [mockIndex, setMockIndex] = useState(0)

  const advice = MOCK_ADVICES[mockIndex]

  return (
    <ScrollView
      style={s.root}
      contentContainerStyle={[
        s.content,
        { paddingTop: insets.top + spacing[6], paddingBottom: TAB_BAR_CLEARANCE + spacing[8] },
      ]}
      showsVerticalScrollIndicator={false}
    >
      {/* Header */}
      <View style={s.header}>
        <Text style={s.appName}>Counsel</Text>
        <Text style={s.tagline}>Before you decide.</Text>
      </View>

      {/* Mock situation label */}
      <View style={s.situationMeta}>
        <Text style={s.situationLabel}>SITUATION</Text>
        <Text style={s.situationText}>
          {mockIndex === 0
            ? 'Salary negotiation with a competing offer'
            : mockIndex === 1
            ? 'Difficult conversation with a colleague'
            : 'Business deal negotiation stalled'}
        </Text>
      </View>

      {/* Advice Card */}
      <AdviceCard advice={advice} />

      {/* Dev-only mock cycle button */}
      {__DEV__ && (
        <Pressable
          style={({ pressed }) => [s.devButton, pressed && { opacity: 0.6 }]}
          onPress={() => setMockIndex((i) => (i + 1) % MOCK_ADVICES.length)}
        >
          <Text style={s.devButtonText}>
            dev: next mock ({mockIndex + 1}/{MOCK_ADVICES.length})
          </Text>
        </Pressable>
      )}
    </ScrollView>
  )
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const s = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: colors.bg.base,
  },
  content: {
    paddingHorizontal: spacing[5],
    gap: spacing[5],
  },
  header: {
    gap: spacing[1],
    marginBottom: spacing[2],
  },
  appName: {
    fontFamily: 'Fraunces_900Black',
    fontSize: typeScale.display.fontSize,
    lineHeight: typeScale.display.lineHeight,
    color: colors.text.primary,
    letterSpacing: -0.8,
  },
  tagline: {
    fontFamily: 'Inter_400Regular',
    fontSize: typeScale.small.fontSize,
    color: colors.text.tertiary,
    letterSpacing: 0.2,
  },
  situationMeta: {
    gap: spacing[2],
  },
  situationLabel: {
    fontFamily: 'Inter_600SemiBold',
    fontSize: typeScale.tiny.fontSize,
    lineHeight: typeScale.tiny.lineHeight,
    color: colors.text.tertiary,
    letterSpacing: 1.2,
  },
  situationText: {
    fontFamily: 'Inter_400Regular',
    fontSize: typeScale.body.fontSize,
    lineHeight: typeScale.body.lineHeight,
    color: colors.text.secondary,
  },
  devButton: {
    alignSelf: 'center',
    borderWidth: 1,
    borderColor: colors.border.strong,
    borderRadius: radii.md,
    paddingHorizontal: spacing[4],
    paddingVertical: spacing[2],
    marginTop: spacing[4],
  },
  devButtonText: {
    fontFamily: 'Inter_400Regular',
    fontSize: typeScale.tiny.fontSize,
    color: colors.text.tertiary,
    letterSpacing: 0.3,
  },
})

