  outcomesRow: {
    flexDirection: 'row',
    gap: spacing[2],
  },
  outcomeChip: {
    flex: 1,
    borderWidth: 1,
    borderRadius: radii.md,
    padding: spacing[3],
    gap: spacing[2],
    backgroundColor: colors.bg.elevated,
  },
  outcomeLabel: {
    fontFamily: 'Inter_700Bold',
    fontSize: 9,
    letterSpacing: 1,
  },
  outcomeText: {
    fontFamily: 'Inter_400Regular',
