            <Pressable onPress={clearCurrent} style={({ pressed }) => [pressed && { opacity: 0.6 }]}>
              <Text style={s.newSitText}>← New situation</Text>
            </Pressable>
          </View>
        </Animated.View>
      )}
    </ScrollView>
  )
}

