    backgroundColor: colors.accent.default,
    paddingVertical: 14,
    borderRadius: radii.lg,
    alignItems: 'center',
  },
  submitBtnDisabled: { opacity: 0.45 },
  submitText: {
    fontFamily: 'Inter_600SemiBold',
    fontSize: typeScale.body.fontSize,
