import { useEffect } from 'react'
import { View, StyleSheet } from 'react-native'
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withSequence,
  withTiming,
  withDelay,
} from 'react-native-reanimated'
import { colors } from '@/lib/design/tokens'

// Pre-defined bar configs: [minHeight, maxHeight, duration, initialDelay]
const BAR_CONFIGS: [number, number, number, number][] = [
  [8, 18, 320, 0],
  [14, 28, 260, 80],
  [10, 32, 290, 40],
  [12, 24, 310, 120],
  [8, 20, 280, 60],
]

function WaveBar({
  minH,
  maxH,
  duration,
  delay,
  active,
}: {
  minH: number
  maxH: number
  duration: number
  delay: number
  active: boolean
}) {
  const height = useSharedValue(minH)

  useEffect(() => {
    if (active) {
      height.value = withDelay(
        delay,
        withRepeat(
          withSequence(
            withTiming(maxH, { duration }),
            withTiming(minH, { duration }),
          ),
          -1,
          false,
        ),
      )
    } else {
      height.value = withTiming(minH, { duration: 200 })
    }
  }, [active])

  const style = useAnimatedStyle(() => ({ height: height.value }))

  return <Animated.View style={[s.bar, style]} />
}

export default function VoiceWaveform({ active }: { active: boolean }) {
  return (
    <View style={s.row}>
      {BAR_CONFIGS.map(([minH, maxH, dur, delay], i) => (
        <WaveBar
          key={i}
          minH={minH}
          maxH={maxH}
          duration={dur}
          delay={delay}
          active={active}
        />
      ))}
    </View>
  )
}

const s = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
    height: 32,
  },
  bar: {
    width: 3,
    borderRadius: 2,
    backgroundColor: colors.accent.default,
  },
})

import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'
import AsyncStorage from '@react-native-async-storage/async-storage'
import { chat } from '@/lib/ai/client'
import { buildSimulatorPrompt, SCORECARD_SYSTEM_PROMPT } from '@/lib/ai/prompts'
import { SCENARIOS } from '@/lib/scenarios'

export type Turn = {
  role: 'user' | 'counterparty'
  content: string
  ts: number
}

export type ScoreCard = {
  anchoring: number
  framing: number
  concessionDiscipline: number
  overall: number
  feedback: string[]
}

export type ScenarioSession = {
  id: string
  scenarioId: string
  persona: string
  difficulty: 1 | 2 | 3
  turns: Turn[]
  status: 'active' | 'completed'
  score?: ScoreCard
  createdAt: string
}

type ScenarioState = {
  activeSession: ScenarioSession | null
  sessions: ScenarioSession[]
  isTyping: boolean
  scoringError: string | null
}

type ScenarioActions = {
  startScenario: (scenarioId: string, persona: string, difficulty: 1 | 2 | 3) => void
  sendMessage: (text: string) => Promise<void>
  endAndScore: () => Promise<void>
  clearActive: () => void
}

export const useScenarioStore = create<ScenarioState & ScenarioActions>()(
  persist(
    (set, get) => ({
      activeSession: null,
      sessions: [],
      isTyping: false,
      scoringError: null,

      startScenario: (scenarioId, persona, difficulty) => {
        const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
        const session: ScenarioSession = {
          id,
          scenarioId,
          persona,
          difficulty,
          turns: [],
          status: 'active',
          createdAt: new Date().toISOString(),
        }
        set({ activeSession: session, scoringError: null })
      },

      sendMessage: async (text) => {
        const session = get().activeSession
        if (!session) return

        const userTurn: Turn = { role: 'user', content: text, ts: Date.now() }
        const withUser: ScenarioSession = {
          ...session,
          turns: [...session.turns, userTurn],
        }
        set({ activeSession: withUser, isTyping: true })

        const scenario = SCENARIOS.find(s => s.id === session.scenarioId)
        if (!scenario) {
          set({ isTyping: false })
          return
        }

        try {
          const systemPrompt = buildSimulatorPrompt(
            session.persona,
            scenario.title,
            scenario.setup,
            session.difficulty,
          )

          // Build message history
          const messages = [
            { role: 'system' as const, content: systemPrompt },
            ...withUser.turns.map(t => ({
              role: (t.role === 'user' ? 'user' : 'assistant') as 'user' | 'assistant',
              content: t.content,
            })),
          ]

          const reply = await chat(messages, { temperature: 0.85, maxTokens: 250 })

          const counterTurn: Turn = { role: 'counterparty', content: reply.trim(), ts: Date.now() }
          set(state => ({
            activeSession: state.activeSession
              ? { ...state.activeSession, turns: [...state.activeSession.turns, counterTurn] }
              : null,
            isTyping: false,
          }))
        } catch {
          set({ isTyping: false })
        }
      },

      endAndScore: async () => {
        const session = get().activeSession
        if (!session) return

        const completed: ScenarioSession = { ...session, status: 'completed' }
        set(state => ({
          activeSession: completed,
          sessions: [completed, ...state.sessions.filter(s => s.id !== session.id)],
          scoringError: null,
        }))

        try {
          const transcript = session.turns
            .map(t => `${t.role === 'user' ? 'You' : 'Counterparty'}: ${t.content}`)
            .join('\n\n')

          const raw = await chat(
            [
              { role: 'system', content: SCORECARD_SYSTEM_PROMPT },
              { role: 'user', content: `Evaluate this negotiation session:\n\n${transcript}` },
            ],
            { jsonMode: true, temperature: 0.4, maxTokens: 800 },
          )

          let score: ScoreCard
          try {
            score = JSON.parse(raw) as ScoreCard
          } catch {
            const match = raw.match(/\{[\s\S]*\}/)
            score = match ? (JSON.parse(match[0]) as ScoreCard) : { anchoring: 5, framing: 5, concessionDiscipline: 5, overall: 5, feedback: [] }
          }

          const scored = { ...completed, score }
          set(state => ({
            activeSession: scored,
            sessions: state.sessions.map(s => (s.id === session.id ? scored : s)),
          }))
        } catch {
          set({ scoringError: 'Scoring failed — session saved.' })
        }
      },

      clearActive: () => set({ activeSession: null, scoringError: null }),
    }),
    {
      name: 'counsel.scenarios.v1',
      storage: createJSONStorage(() => AsyncStorage),
      partialize: (state) => ({ sessions: state.sessions }),
    },
  ),
)

import React, { useEffect, useState } from 'react'
import { View, StyleSheet, Platform, DeviceEventEmitter, Text as RNText } from 'react-native'
import { Stack, useNavigationContainerRef, usePathname } from 'expo-router'
import { QueryClientProvider } from '@tanstack/react-query'
import { queryClient } from '@/lib/queryClient'
import * as Sentry from '@sentry/react-native'

const routingInstrumentation = Sentry.reactNavigationIntegration()

Sentry.init({
  dsn: process.env.EXPO_PUBLIC_SENTRY_DSN ?? '',
  environment: __DEV__ ? 'development' : 'production',
  enabled: !__DEV__ && !!process.env.EXPO_PUBLIC_SENTRY_DSN,
  integrations: [routingInstrumentation],
  tracesSampleRate: 0,
})

import { GestureHandlerRootView } from 'react-native-gesture-handler'
import { BottomSheetModalProvider } from '@gorhom/bottom-sheet'
import { SafeAreaProvider } from 'react-native-safe-area-context'
import { StatusBar } from 'expo-status-bar'
import { useFonts } from 'expo-font'
import {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  Inter_800ExtraBold,
} from '@expo-google-fonts/inter'
import {
  Fraunces_400Regular,
  Fraunces_700Bold,
  Fraunces_900Black,
} from '@expo-google-fonts/fraunces'
import { ThemeProvider, DarkTheme } from '@react-navigation/native'
import { PostHogProvider } from 'posthog-react-native'
import { I18nextProvider } from 'react-i18next'

import { supabase, isSupabaseEnabled } from '@/lib/supabase'
import { posthog, isPostHogEnabled, identify, resetIdentity, track } from '@/lib/analytics'
import { configureRevenueCat, loginRevenueCat, logoutRevenueCat } from '@/lib/purchases'
import { SubscriptionProvider } from '@/contexts/SubscriptionContext'
import { ToastProvider } from '@/contexts/ToastContext'
import i18n, { initI18n } from '@/lib/i18n'
import OfflineBanner from '@/components/OfflineBanner'
import OfflineOverlay from '@/components/OfflineOverlay'
import { Text } from '@/components/ui/Text'
import { BG } from '@/lib/theme'

// ─── Error boundary ───────────────────────────────────────────────────────────
// React requires a class component to catch render errors — hooks cannot do this.

function ErrorFallback() {
  return (
    <View style={eb.container}>
      <Text style={eb.title}>Something went wrong</Text>
      <Text style={eb.subtitle}>Please close and reopen the app.</Text>
    </View>
  )
}

class ErrorBoundary extends React.Component<
  { children: React.ReactNode },
  { hasError: boolean }
> {
  state = { hasError: false }

  static getDerivedStateFromError() {
    return { hasError: true }
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('[ErrorBoundary] Uncaught error:', error, info)
    Sentry.captureException(error, { extra: { componentStack: info.componentStack } })
  }

  render() {
    if (this.state.hasError) return <ErrorFallback />
    return this.props.children
  }
}

const splash = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: '#0a0a0a',
    alignItems: 'center',
    justifyContent: 'center',
  },
  wordmark: {
    fontFamily: 'Fraunces_700Bold',
    fontSize: 32,
    color: '#f5f5f5',
    letterSpacing: -0.5,
  },
})

const eb = StyleSheet.create({
  container: {
    flex: 1, backgroundColor: BG,
    alignItems: 'center', justifyContent: 'center', padding: 32,
  },
  title: { color: '#fff', fontSize: 18, fontWeight: '700', marginBottom: 10, textAlign: 'center' },
  subtitle: { color: 'rgba(255,255,255,0.4)', fontSize: 14, textAlign: 'center', lineHeight: 22 },
})

// ─── Theme ────────────────────────────────────────────────────────────────────

const customDarkTheme = {
  ...DarkTheme,
  colors: { ...DarkTheme.colors, background: BG },
}

// ─── Conditional PostHog provider ─────────────────────────────────────────────
// PostHogProvider requires a valid client instance. When the API key is missing
// we skip the provider entirely so no errors are thrown.

function MaybePostHogProvider({ children }: { children: React.ReactNode }) {
  if (isPostHogEnabled && posthog) {
    return <PostHogProvider client={posthog}>{children}</PostHogProvider>
  }
  return <>{children}</>
}

// ─── Screen tracking ─────────────────────────────────────────────────────────
// Rendered inside the navigator so usePathname has routing context.

function ScreenTracker() {
  const pathname = usePathname()
  useEffect(() => {
    track('screen_viewed', { screen: pathname })
  }, [pathname])
  return null
}

// ─── Root layout ──────────────────────────────────────────────────────────────

function RootLayout() {
  const navigationRef = useNavigationContainerRef()
  const [fontsLoaded] = useFonts({
    Inter_400Regular,
    Inter_500Medium,
    Inter_600SemiBold,
    Inter_700Bold,
    Inter_800ExtraBold,
    Fraunces_400Regular,
    Fraunces_700Bold,
    Fraunces_900Black,
  })

  // null = still checking; true/false = auth state known
  const [isAuthed, setIsAuthed] = useState<boolean | null>(null)
  // null = loading; false = not completed; true = completed
  const [onboardingCompleted, setOnboardingCompleted] = useState<boolean | null>(null)
  const [i18nReady, setI18nReady] = useState(false)

  useEffect(() => {
    initI18n().then(() => setI18nReady(true))
  }, [])

  useEffect(() => {
    if (navigationRef.current) {
      routingInstrumentation.registerNavigationContainer(navigationRef)
    }
  }, [navigationRef])

  useEffect(() => {
    // Configure RevenueCat once at startup, before any user is known
    configureRevenueCat()

    if (!isSupabaseEnabled) {
      // No Supabase credentials — bypass auth for demo
      setIsAuthed(true)
      setOnboardingCompleted(true)
      return
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      setIsAuthed(!!session)
      if (session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
        loginRevenueCat(session.user.id)
        identify(
          session.user.id,
          session.user.email ? { email: session.user.email } : undefined
        )
      } else {
        setOnboardingCompleted(null)
      }
    }).catch(() => {
      console.warn('[Auth] Could not reach Supabase — defaulting to signed-out state.')
      setIsAuthed(false)
    })

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        setIsAuthed(true)
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
        loginRevenueCat(session.user.id)
        identify(
          session.user.id,
          session.user.email ? { email: session.user.email } : undefined
        )
      }
      if (event === 'SIGNED_OUT') {
        setIsAuthed(false)
        setOnboardingCompleted(null)
        logoutRevenueCat()
        resetIdentity()
      }
      if (event === 'USER_UPDATED' && session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
      }
      if (event === 'TOKEN_REFRESHED' && session?.user) {
        setOnboardingCompleted(session.user.user_metadata?.onboarding_completed === true)
      }
    })

    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (!__DEV__) return
    const sub = DeviceEventEmitter.addListener('__dev_skip_auth__', () => {
      setIsAuthed(true)
      setOnboardingCompleted(true)
    })
    return () => sub.remove()
  }, [])

  // Show blank dark screen while session + i18n checks complete.
  // This prevents a flash of wrong content on launch.
  if (!fontsLoaded || isAuthed === null || !i18nReady || (isAuthed === true && onboardingCompleted === null)) {
    return (
      <View style={splash.root}>
        <RNText style={splash.wordmark}>Counsel</RNText>
      </View>
    )
  }

  return (
    <ErrorBoundary>
      <I18nextProvider i18n={i18n}>
        <MaybePostHogProvider>
          <QueryClientProvider client={queryClient}>
          <SubscriptionProvider>
            <ToastProvider>
            <SafeAreaProvider>
              <GestureHandlerRootView style={{ flex: 1, backgroundColor: BG }}>
                <BottomSheetModalProvider>
                  <StatusBar
                    style="light"
                    translucent={Platform.OS === 'android'}
                    backgroundColor={Platform.OS === 'android' ? BG : undefined}
                  />
                  <ThemeProvider value={customDarkTheme}>
                    <View style={{ flex: 1, backgroundColor: BG }}>
                      <Stack ref={navigationRef} screenOptions={{ headerShown: false, animation: 'fade', contentStyle: { backgroundColor: BG } }}>

                        {/* ── Unauthenticated screens ──────────────────────────────────
                        Accessible only when signed out. When isAuthed flips to true,
                        Stack.Protected removes these and Expo Router auto-redirects to
                        the first accessible authenticated screen. */}
                        <Stack.Protected guard={!isAuthed}>
                          <Stack.Screen name="index" />
                          <Stack.Screen name="(auth)" />
                        </Stack.Protected>

                        {/* ── Onboarding screens ───────────────────────────────────────
                        Shown when signed in but onboarding not yet completed. */}
                        <Stack.Protected guard={!!isAuthed && onboardingCompleted === false}>
                          <Stack.Screen name="(onboarding)" />
                        </Stack.Protected>

                        {/* ── Authenticated screens ────────────────────────────────────
                        Accessible only when signed in + onboarding done. */}
                        <Stack.Protected guard={!!isAuthed && onboardingCompleted === true}>
                          <Stack.Screen name="(tabs)" />
                          <Stack.Screen name="advice/[id]" />
                          <Stack.Screen name="scenario/[id]" />
                          <Stack.Screen name="detail/[id]" />
                          <Stack.Screen name="settings" />
                          <Stack.Screen name="support" />
                        </Stack.Protected>

                        {/* ── Always-public screens — declared LAST so they don't become
                        the default redirect target when a protected group flips. ── */}
                        <Stack.Screen name="upgrade" />
                        <Stack.Screen name="privacy" />
                        <Stack.Screen name="terms" />
                      </Stack>
                      <ScreenTracker />
                      <OfflineBanner />
                      <OfflineOverlay />
                    </View>
                  </ThemeProvider>
                </BottomSheetModalProvider>
              </GestureHandlerRootView>
            </SafeAreaProvider>
            </ToastProvider>
          </SubscriptionProvider>
          </QueryClientProvider>
        </MaybePostHogProvider>
      </I18nextProvider>
    </ErrorBoundary>
  )
}

export default Sentry.wrap(RootLayout)

