// Drop the 'import' ESM condition so Metro resolves CJS versions of packages
// instead of their .mjs counterparts. This prevents "Cannot use 'import.meta'
// outside a module" on web — triggered by zustand/esm/middleware.mjs.
// Native picks the 'react-native' condition first so it is unaffected.
config.resolver = {
  ...config.resolver,
  unstable_conditionNames: ['require', 'default'],
}

// Use the default Babel transform profile instead of the Hermes-specific one
// for better web compatibility.
config.transformer = {
  ...config.transformer,
  unstable_transformProfile: 'default',
}

module.exports = config

