import { Platform } from 'react-native'

const BASE_URL = 'https://integrate.api.nvidia.com/v1/chat/completions'
const PRIMARY_MODEL = 'z-ai/glm-5.1'
const FALLBACK_MODEL = 'deepseek-ai/deepseek-v4-flash'
const TIMEOUT_MS = 45_000

export type ChatMessage = {
  role: 'system' | 'user' | 'assistant'
  content: string
}

export class AIRateLimitError extends Error {
  constructor(model: string) {
    super(`Rate limited by model: ${model}`)
    this.name = 'AIRateLimitError'
  }
}

export class AINetworkError extends Error {
  constructor(detail?: string) {
    super(`Network error: ${detail ?? 'unknown'}`)
    this.name = 'AINetworkError'
  }
}

export class AIInvalidResponseError extends Error {
  constructor(detail?: string) {
    super(`Invalid AI response: ${detail ?? 'no content returned'}`)
    this.name = 'AIInvalidResponseError'
  }
}

function getApiKey(): string {
  const key = process.env.EXPO_PUBLIC_NVIDIA_API_KEY
  if (!key) throw new Error('Set EXPO_PUBLIC_NVIDIA_API_KEY in .env.local')
  return key
}

function isAbortError(err: unknown): boolean {
  return err instanceof Error && (err.name === 'AbortError' || err.name === 'CanceledError')
}

async function callModel(
  messages: ChatMessage[],
  model: string,
  temperature: number,
  maxTokens: number,
  signal: AbortSignal,
): Promise<string> {
  let response: Response
  try {
    response = await fetch(BASE_URL, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${getApiKey()}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ model, messages, temperature, max_tokens: maxTokens }),
      signal,
    })
  } catch (err) {
    console.error('[AI] fetch threw:', {
      name: err instanceof Error ? err.name : typeof err,
      message: err instanceof Error ? err.message : String(err),
      stack: err instanceof Error ? err.stack : undefined,
    })
    if (isAbortError(err)) throw err
    throw new AINetworkError(err instanceof Error ? err.message : 'fetch failed')
  }

  console.log('[AI] status:', response.status)

  if (response.status === 429 || response.status >= 500) {
    throw new AIRateLimitError(model)
  }

  if (!response.ok) {
    const body = await response.text().catch(() => 'unknown')
    throw new AIInvalidResponseError(`HTTP ${response.status}: ${body}`)
  }

  const text = await response.text()
  console.log('[AI] raw response (first 200 chars):', text.slice(0, 200))

  let data: { choices?: { message?: { content?: string } }[] }
  try {
    data = JSON.parse(text)
  } catch (err) {
    throw new AIInvalidResponseError(`JSON parse failed: ${err instanceof Error ? err.message : String(err)}`)
  }

  const content = data?.choices?.[0]?.message?.content
  if (!content) throw new AIInvalidResponseError('Empty content in response')
  return content
}

export async function chat(
  messages: ChatMessage[],
  opts?: {
    model?: string
    temperature?: number
    maxTokens?: number
    jsonMode?: boolean
  },
): Promise<string> {
  const key = process.env.EXPO_PUBLIC_NVIDIA_API_KEY
  console.log('[AI] key present:', !!key)
  console.log('[AI] key length:', key?.length ?? 0)
  const primaryModel = opts?.model ?? PRIMARY_MODEL
  console.log('[AI] model:', primaryModel)
  console.log('[AI] platform:', Platform.OS)

  getApiKey()

  const temperature = opts?.temperature ?? 0.7
  const maxTokens = opts?.maxTokens ?? 1024

  const finalMessages: ChatMessage[] = opts?.jsonMode
    ? [
        ...messages,
        {
          role: 'system',
          content: 'Respond with strictly valid JSON only. No prose, no markdown fences.',
        },
      ]
    : messages

  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS)

  try {
    try {
      const result = await callModel(finalMessages, primaryModel, temperature, maxTokens, controller.signal)
      if (__DEV__) console.info(`[Counsel AI] Served by ${primaryModel}`)
      return result
    } catch (primaryErr) {
      if (isAbortError(primaryErr)) throw new AINetworkError('Request timed out after 45s')

      if (primaryErr instanceof AIRateLimitError || primaryErr instanceof AINetworkError) {
        if (__DEV__) console.info(`[Counsel AI] Primary failed, falling back to ${FALLBACK_MODEL}`)
        const result = await callModel(finalMessages, FALLBACK_MODEL, temperature, maxTokens, controller.signal)
        if (__DEV__) console.info(`[Counsel AI] Served by fallback ${FALLBACK_MODEL}`)
        return result
      }

      throw primaryErr
    }
  } catch (err) {
    if (isAbortError(err)) throw new AINetworkError('Request timed out after 45s')
    throw err
  } finally {
    clearTimeout(timer)
  }
}

