    headers?: Record<string, string>
    body?: string
    timeout?: number
  },
): Promise<XHRResponse> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest()
    xhr.open(opts.method ?? 'POST', url)
