import { Platform } from 'react-native'

const NVIDIA_URL = 'https://integrate.api.nvidia.com/v1/chat/completions'
const PRIMARY_MODEL = 'z-ai/glm-5.1'
const FALLBACK_MODEL = 'deepseek-ai/deepseek-v4-flash'
const TIMEOUT_MS = 90_000

// When EXPO_PUBLIC_DEV_PROXY=1, route through the local Node proxy instead of
// hitting NVIDIA directly. The proxy injects the real API key server-side,
// which avoids Android TLS/fetch issues on the emulator/device.
function getBaseUrl(): string {
  if (process.env.EXPO_PUBLIC_DEV_PROXY === '1') {
    const host = process.env.EXPO_PUBLIC_DEV_PROXY_HOST ?? 'localhost'
    return `http://${host}:8787/v1/chat/completions`
  }
  return NVIDIA_URL
}

export type ChatMessage = {
  role: 'system' | 'user' | 'assistant'
  content: string
}

export class AIRateLimitError extends Error {
  constructor(model: string) {
    super(`Rate limited by model: ${model}`)
    this.name = 'AIRateLimitError'
  }
}

#!/usr/bin/env node
/**
 * dev-proxy.js — forwards POST /v1/chat/completions → NVIDIA NIM, injecting
 * the real API key server-side. Run on your dev machine so Android devices on
 * the same LAN can reach NVIDIA without needing the key on-device.
 *
 * Usage:
 *   npm run dev:proxy
 *
 * Then in .env.local:
 *   EXPO_PUBLIC_DEV_PROXY=1
 *   EXPO_PUBLIC_DEV_PROXY_HOST=<your LAN IP>
 */

const http = require('http')
const https = require('https')
const fs = require('fs')
const path = require('path')

// ---------------------------------------------------------------------------
// Load .env.local without any third-party deps
// ---------------------------------------------------------------------------
function loadEnvLocal() {
  const envPath = path.join(__dirname, '..', '.env.local')
  try {
    const lines = fs.readFileSync(envPath, 'utf8').split('\n')
    const env = {}
    for (const line of lines) {
      const trimmed = line.trim()
      if (!trimmed || trimmed.startsWith('#')) continue
      const eqIdx = trimmed.indexOf('=')
      if (eqIdx < 0) continue
      const k = trimmed.slice(0, eqIdx).trim()
      // Strip optional surrounding quotes from the value
      const raw = trimmed.slice(eqIdx + 1).trim()
      env[k] = raw.replace(/^['"]|['"]$/g, '')
    }
    return env
  } catch {
    return {}
  }
}

const fileEnv = loadEnvLocal()
const API_KEY =
  process.env.EXPO_PUBLIC_NVIDIA_API_KEY ||
  fileEnv.EXPO_PUBLIC_NVIDIA_API_KEY

if (!API_KEY) {
  console.error('[proxy] ERROR: EXPO_PUBLIC_NVIDIA_API_KEY not found in .env.local or environment.')
  process.exit(1)
}

// ---------------------------------------------------------------------------
// Proxy config
// ---------------------------------------------------------------------------
const PROXY_PORT = 8787
const TARGET_HOST = 'integrate.api.nvidia.com'
const TARGET_PATH = '/v1/chat/completions'

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------
const server = http.createServer((req, res) => {
  // CORS preflight (useful when testing from a browser)
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    })
    res.end()
    return
  }

  if (req.method !== 'POST' || req.url !== '/v1/chat/completions') {
    res.writeHead(404, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: 'Not found — only POST /v1/chat/completions is supported.' }))
    return
  }

  // Collect the client request body
  const chunks = []
  req.on('data', chunk => chunks.push(chunk))
  req.on('end', () => {
    const body = Buffer.concat(chunks)
    console.log(`[proxy] → ${TARGET_HOST}${TARGET_PATH}  (${body.length} bytes)`)

    const options = {
      hostname: TARGET_HOST,
      port: 443,
      path: TARGET_PATH,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
        Authorization: `Bearer ${API_KEY}`,
      },
    }

    const proxyReq = https.request(options, proxyRes => {
      console.log(`[proxy] ← status ${proxyRes.statusCode}`)
      res.writeHead(proxyRes.statusCode ?? 502, {
        'Content-Type': proxyRes.headers['content-type'] ?? 'application/json',
        'Access-Control-Allow-Origin': '*',
      })
      proxyRes.pipe(res)
    })

    proxyReq.on('error', err => {
      console.error('[proxy] upstream error:', err.message)
      if (!res.headersSent) {
        res.writeHead(502, { 'Content-Type': 'application/json' })
        res.end(JSON.stringify({ error: `Proxy upstream error: ${err.message}` }))
      }
    })

    proxyReq.write(body)
    proxyReq.end()
  })

  req.on('error', err => {
    console.error('[proxy] client request error:', err.message)
  })
})

server.listen(PROXY_PORT, '0.0.0.0', () => {
  const maskedKey = `${API_KEY.slice(0, 8)}...${API_KEY.slice(-4)}`
  console.log(`[proxy] Listening on http://0.0.0.0:${PROXY_PORT}`)
  console.log(`[proxy] API key: ${maskedKey}`)
  console.log(`[proxy] Forwarding to https://${TARGET_HOST}${TARGET_PATH}`)
  console.log(`[proxy] ─────────────────────────────────────────────`)
  console.log(`[proxy] In .env.local, set:`)
  console.log(`[proxy]   EXPO_PUBLIC_DEV_PROXY=1`)
  console.log(`[proxy]   EXPO_PUBLIC_DEV_PROXY_HOST=<your LAN IP>`)
  console.log(`[proxy] Find your LAN IP with: ipconfig (Windows) / ifconfig (Mac)`)
})

